import numpy as np

def make_obs(agent_cells, reward_pos, prev=True):
    X = np.zeros((1, 500))
    # wall border in channel 3
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                X[0, (r * 10 + c) * 5 + 3] = 1
    # agent cells in channel 0
    for (r, c) in agent_cells:
        X[0, (r * 10 + c) * 5 + 0] = 1
    # reward target in channel 2
    r, c = reward_pos
    X[0, (r * 10 + c) * 5 + 2] = 1
    # previous frame in channel 4 (same cells as current agent)
    if prev:
        for (r, c) in agent_cells:
            X[0, (r * 10 + c) * 5 + 4] = 1
    return X

cases = [
    ("single_reward_right", [(4, 4)], (4, 7)),
    ("horiz3_reward_right", [(4, 2), (4, 3), (4, 4)], (4, 7)),
    ("vert3_reward_right", [(2, 4), (3, 4), (4, 4)], (4, 7)),
    ("horiz3_reward_left", [(4, 2), (4, 3), (4, 4)], (4, 1)),
    ("horiz3_reward_up", [(4, 2), (4, 3), (4, 4)], (1, 4)),
]

for name, agent, reward in cases:
    X = make_obs(agent, reward)
    logits = forward(X)[0]
    print(f"{name}: argmax={np.argmax(logits)} logits={np.round(logits, 2)}")
